CREATE TYPE "AcademicYearStatus" AS ENUM ('PREPARATION', 'ACTIVE', 'CLOSED');
CREATE TYPE "EnrollmentStatus" AS ENUM ('ACTIVE', 'TRANSFERRED', 'LEFT', 'ARCHIVED');

CREATE TABLE "AcademicYear" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "name" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "status" "AcademicYearStatus" NOT NULL DEFAULT 'PREPARATION', "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AcademicYear_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Semester" ("id" TEXT NOT NULL, "academicYearId" TEXT NOT NULL, "number" INTEGER NOT NULL, "name" TEXT NOT NULL, "startsAt" TIMESTAMP(3) NOT NULL, "endsAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Semester_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Level" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "name" TEXT NOT NULL, "sortOrder" INTEGER NOT NULL DEFAULT 0, "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Level_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Series" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "levelId" TEXT, "name" TEXT NOT NULL, "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Series_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Classroom" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "academicYearId" TEXT NOT NULL, "levelId" TEXT NOT NULL, "seriesId" TEXT, "name" TEXT NOT NULL, "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Classroom_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Student" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "matricule" TEXT NOT NULL, "lastName" TEXT NOT NULL, "firstNames" TEXT NOT NULL, "birthDate" TIMESTAMP(3), "birthPlace" TEXT, "sex" TEXT, "address" TEXT, "guardianName" TEXT, "guardianPhone" TEXT, "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Student_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Enrollment" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "studentId" TEXT NOT NULL, "classroomId" TEXT NOT NULL, "status" "EnrollmentStatus" NOT NULL DEFAULT 'ACTIVE', "enrolledAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "endedAt" TIMESTAMP(3), "deletedAt" TIMESTAMP(3), CONSTRAINT "Enrollment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Subject" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "name" TEXT NOT NULL, "code" TEXT NOT NULL, "deletedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Subject_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ClassroomSubject" ("id" TEXT NOT NULL, "schoolId" TEXT NOT NULL, "classroomId" TEXT NOT NULL, "subjectId" TEXT NOT NULL, "coefficient" DECIMAL(6,2) NOT NULL, "effectiveFrom" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "effectiveTo" TIMESTAMP(3), CONSTRAINT "ClassroomSubject_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AcademicYear_schoolId_name_key" ON "AcademicYear"("schoolId", "name"); CREATE UNIQUE INDEX "Semester_academicYearId_number_key" ON "Semester"("academicYearId", "number"); CREATE UNIQUE INDEX "Level_schoolId_name_key" ON "Level"("schoolId", "name"); CREATE UNIQUE INDEX "Series_schoolId_levelId_name_key" ON "Series"("schoolId", "levelId", "name"); CREATE UNIQUE INDEX "Classroom_schoolId_academicYearId_name_key" ON "Classroom"("schoolId", "academicYearId", "name"); CREATE UNIQUE INDEX "Student_schoolId_matricule_key" ON "Student"("schoolId", "matricule"); CREATE UNIQUE INDEX "Subject_schoolId_code_key" ON "Subject"("schoolId", "code");
ALTER TABLE "AcademicYear" ADD CONSTRAINT "AcademicYear_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id"); ALTER TABLE "Semester" ADD CONSTRAINT "Semester_academicYearId_fkey" FOREIGN KEY ("academicYearId") REFERENCES "AcademicYear"("id"); ALTER TABLE "Level" ADD CONSTRAINT "Level_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id"); ALTER TABLE "Series" ADD CONSTRAINT "Series_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id"); ALTER TABLE "Series" ADD CONSTRAINT "Series_levelId_fkey" FOREIGN KEY ("levelId") REFERENCES "Level"("id"); ALTER TABLE "Classroom" ADD CONSTRAINT "Classroom_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id"); ALTER TABLE "Classroom" ADD CONSTRAINT "Classroom_academicYearId_fkey" FOREIGN KEY ("academicYearId") REFERENCES "AcademicYear"("id"); ALTER TABLE "Classroom" ADD CONSTRAINT "Classroom_levelId_fkey" FOREIGN KEY ("levelId") REFERENCES "Level"("id"); ALTER TABLE "Classroom" ADD CONSTRAINT "Classroom_seriesId_fkey" FOREIGN KEY ("seriesId") REFERENCES "Series"("id"); ALTER TABLE "Student" ADD CONSTRAINT "Student_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id"); ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "Student"("id"); ALTER TABLE "Enrollment" ADD CONSTRAINT "Enrollment_classroomId_fkey" FOREIGN KEY ("classroomId") REFERENCES "Classroom"("id"); ALTER TABLE "Subject" ADD CONSTRAINT "Subject_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id"); ALTER TABLE "ClassroomSubject" ADD CONSTRAINT "ClassroomSubject_classroomId_fkey" FOREIGN KEY ("classroomId") REFERENCES "Classroom"("id"); ALTER TABLE "ClassroomSubject" ADD CONSTRAINT "ClassroomSubject_subjectId_fkey" FOREIGN KEY ("subjectId") REFERENCES "Subject"("id");
